<script setup lang="ts">import type{Product}from'~/data/products';defineProps<{product:Product;large?:boolean}>()</script><template><div class="product-visual" :class="[{large},`visual-${product.visual}`]" :style="{background:product.tone}"><span class="material-pill">{{ product.material }}</span><div v-if="large" class="visual-grid"/><div class="visual-art"><template v-if="product.visual==='headset'"><div class="headset-body"/><div class="headset-hole"/></template><template v-else-if="product.visual==='duna'"><i v-for="i in 9" :key="i" class="duna-line" :style="{width:`${70+(5-Math.abs(5-i))*13}px`}"/></template><template v-else-if="product.visual==='controller'"><div class="controller-base"/><div class="controller-knob k1"/><div class="controller-knob k2"/></template><template v-else-if="product.visual==='modular'"><div class="modular-body"/><div class="modular-slot s1"/><div class="modular-slot s2"/></template><template v-else-if="product.visual==='orbit'"><div class="orbit-body"><i/><i/><i/></div></template><template v-else><div class="desk-body"><i/><i/><i/></div></template></div><span v-if="large" class="object-code">DUNA / OBJETO 04</span></div></template>